// Мок для getTasks
export const mockGetTasks = (): Promise<ITaskListResponse> => {
  return new Promise((resolve) => {
    setTimeout(() => {
      resolve({
        tasks: mockTasks,
      });
    }, 500);
  });
};

// Мок для executeTask
export const mockExecuteTask = (taskId: number): Promise<ITask> => {
  return new Promise((resolve) => {
    setTimeout(() => {
      const task = mockTasks.find((t) => t.id === taskId);
      if (task) {
        const updatedTask: ITask = {
          ...task,
          status: 'REVIEW',
          canParticipate: false,
        };
        resolve(updatedTask);
      } else {
        resolve(mockTasks[0]);
      }
    }, 500);
  });
};

// Мок для executeOtherTask
export const mockExecuteOtherTask = (
  taskId: number,
  text: string,
  fileIds?: number[]
): Promise<ITask> => {
  return new Promise((resolve) => {
    setTimeout(() => {
      const task = mockTasks.find((t) => t.id === taskId && t.type === 'OTHER') as ITask;
      if (task && task.type === 'OTHER') {
        const newMessage: IOtherTaskMessage = {
          id: Date.now(),
          type: fileIds && fileIds.length > 0 ? 'FILE_LIST' : 'TEXT',
          text: fileIds && fileIds.length > 0 ? null : text,
          files:
            fileIds && fileIds.length > 0
              ? fileIds.map((id) => ({
                  id,
                  url: `https://via.placeholder.com/200?text=File${id}`,
                  fileName: `file-${id}.pdf`,
                  size: 102400,
                }))
              : undefined,
          createdDate: new Date().toISOString(),
          isMine: true,
        };
        console.log(newMessage);

        const updatedTask: ITask = {
          ...task,
          status: 'REVIEW',
          canParticipate: false,
          // messages: [(...task?.messages as IOtherTaskMessag), newMessage],
        };
        resolve(updatedTask);
      } else {
        resolve(mockTasks[0]);
      }
    }, 500);
  });
};

// Мок для sendMessageForOtherTask
export const mockSendMessageForOtherTask = (
  taskId: number,
  message: string,
  fileIds?: number[]
): Promise<IOtherTaskMessage[]> => {
  return new Promise((resolve) => {
    setTimeout(() => {
      console.log(taskId);
      const newMessage: IOtherTaskMessage = {
        id: Date.now(),
        type: fileIds && fileIds.length > 0 ? 'FILE_LIST' : 'TEXT',
        text: fileIds && fileIds.length > 0 ? null : message,
        files:
          fileIds && fileIds.length > 0
            ? fileIds.map((id) => ({
                id,
                url: `https://via.placeholder.com/200?text=File${id}`,
                fileName: `file-${id}.pdf`,
                size: 102400,
              }))
            : undefined,
        createdDate: new Date().toISOString(),
        isMine: true,
      };

      resolve([newMessage]);
    }, 500);
  });
};

